func (e *parserErrorStack) add(pe parseError) {
	if base, n := e.scopeBase(), len(e.stack); n > base {
		if top := e.stack[n-1].rank(); pe.rank() < top {
			return
		} else if pe.rank() > top {
			e.stack = e.stack[:base]
		}
	}
	e.stack = append(e.stack, pe)
}

